\mathsf{Ctx}_{\mathsf{Eff}}
=
\bigcup_{n\in\mathbb N}
\left\{
\langle x_i:A_i\rangle_{i<n}:
\forall i<n\ (x_i\in\mathsf{Var}_{\mathsf E}\land A_i\in\mathsf{Ty}_{\mathsf E})
\land\forall i<j<n\ x_i\ne x_j
\right\}.

\mathsf{ValFormRule}_{\mathsf E}
=\{(\langle\rangle,\star)\}
\cup\{(\langle\rangle,\lambda x.t):x\in\mathsf{Var}_{\mathsf E},t\in\mathsf{Tm}_{\mathsf E}\}
\cup\{(\langle a,b\rangle,\langle a,b\rangle):a,b\in\mathsf{Tm}_{\mathsf E}\}.

(\lambda y.t)[x:=s]=
\begin{cases}
\lambda y.t,&y=x,\\
\lambda y.t[x:=s],&y\ne x,\ y\notin\operatorname{FV}(s),\\
\lambda z.(t[y:=z])[x:=s],&y\ne x,\ y\in\operatorname{FV}(s).
\end{cases}

\mathsf{RootStep}_{\mathsf E}
=
\{((\lambda x.t)\,v,\varnothing,t[x:=v]):v\in\mathsf{Val}_{\mathsf E},\ t\in\mathsf{Tm}_{\mathsf E}\}
\cup
\{(\pi_1\langle a,b\rangle,\varnothing,a),(\pi_2\langle a,b\rangle,\varnothing,b):a,b\in\mathsf{Val}_{\mathsf E}\}
\cup
\{(\operatorname{op}_e(v),\operatorname{opLab}_{\mathsf E}(e),v):e\in\mathsf{EffAtom},\ v\in\mathsf{Val}_{\mathsf E}\}
\cup
\{(\operatorname{let}\ x=v\ \operatorname{in}\ u,\varnothing,u[x:=v]):v\in\mathsf{Val}_{\mathsf E},\ u\in\mathsf{Tm}_{\mathsf E}\}.
